{
  "category_edits": [
    {
      "category": "sequence_interest",
      "rationale": "Across all four category models, shorten causal pooling from four states to three while retaining the 0.8 current-state and 0.2 recent-mean blend. This tests whether a narrower window reduces stale-interest smoothing. Existing padding masks and final-real-position inference remain intact; checkpoint metadata and the embedded predictor check agree.",
      "edits": [
        {
          "find": "        starts = (torch.arange(length, device=seq.device) - 3).clamp(min=0)",
          "replace": "        starts = (torch.arange(length, device=seq.device) - 2).clamp(min=0)"
        },
        {
          "find": "            \"sequence_readout\": \"causal_recent4_blend_0.2\",",
          "replace": "            \"sequence_readout\": \"causal_recent3_blend_0.2\","
        },
        {
          "find": "        if meta.get(\"sequence_readout\") != \"causal_recent4_blend_0.2\":",
          "replace": "        if meta.get(\"sequence_readout\") != \"causal_recent3_blend_0.2\":"
        }
      ]
    }
  ],
  "change_summary": "Use padding-aware causal three-state pooling across all four NextItNet category models, with matching checkpoint metadata and predictor validation."
}
